from pathlib import Path
import sys, json, shutil, hashlib
HERE=Path(__file__).resolve().parent
sys.path.insert(0,str(HERE.parent))
from mcp_call import Client

identity='Compact shaggy wolf with warm olive-brown upper back, ochre round flank spots, tall triangular pointed brown ears, brown rear crown and cheek ruff, ivory-white angular eyebrows and long centered white muzzle, large ivory-white eye sclera with tiny dark pupils (NOT glowing amber eyes), dark brown oval nose, small ivory fangs, broad white pointed chest/neck ruff, four short brown upper legs with white lower paws, and a full ivory-white bushy curved tail with taupe shaded underside. No collar, armor, dorsal spines or saddle.'
plan=json.loads((HERE/'anatomy_plan.json').read_text(encoding='utf-8'))
shutil.copy2(HERE/'anatomy_plan.json',HERE/'anatomy_plan_before_review_20261029.json')
plan.update(identity=identity,source_art_review={'method':'Viewed complete original atlas and complete serialized source prefab reference; read battle/source hierarchy and anchors.','findings':['Tall pointed brown ears, unlike the previous rounded-ear warg.','Ivory eye whites with black pupils; the generic amber-eye description is inaccurate.','Whole tail ivory with taupe underside, not only a white tip.','Brown torso with white shoulder ruff and ochre spots; no dorsal spines.','Four canine legs: fore and hind roots remain attached; Up smooth rear heels and Down toe lines.'],'attachment_plan':'Axial elevated quadruped. Up neck/head at far top, white shoulder ruff below rear head, brown rump below, tail rooted into rump and sweeping down. Down far brown rump above white chest, head overlaps chest below; tail behind far rump. Mirrored leg pairs, opposite diagonal phases, short stride, small torso roll and restrained tail swing.','native_side_contract':'Retain all original Wolf float/PPtr curves, head events, controller parameters, lengths and loops; copy and append vertical curves only.'})
(HERE/'anatomy_plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for direction in ['Up','Down']:
    file=HERE/'generation'/direction/'prompt.txt'
    shutil.copy2(file,file.with_name('prompt_before_art_review_20261029.txt'))
    rear=direction=='Up'
    view=('Strict rear view travelling toward screen UP. Rear crown is brown with two tall solid brown outer ear backs and a pointed brown cheek-fur silhouette; NO eyes, eyebrows, muzzle, nose, mouth, teeth, nostrils, inner-ear pads or face. The only white head-edge fur is a small natural cheek/neck edge, not a second face. All three heads are exactly the SAME plain back head. The white shoulder ruff belongs to the BODY, not a second mane on the head. Rear paws have smooth rounded white heels, NO front toe/claw lines.' if rear else 'Strict front view travelling toward screen DOWN. Symmetric pointed brown ears with ivory inner ear, ivory eyebrows, ivory eyes and small black pupils, white face and long centered muzzle, dark brown nose, ochre cheek spots and small ivory fangs. Normal head closed mouth, Angry open snarling mouth with teeth, Dead original drooping dead face and ochre tongue. No three-quarter view. White paws show front toe divisions, no rear heel posing as toes.')
    body=('neck at TOP, broad rump below; WHITE pointed shoulder collar only at top, BROWN upper back and rump, ochre flank spots, no face' if rear else 'far rump at TOP, near white shoulder/chest ruff at BOTTOM; brown back and ochre flank spots, no head')
    feet='smooth round rear white heel, NO toe lines, claws, paw pads or foot soles' if rear else 'white lower forepaw with front toe divisions and rounded small ivory claws'
    prompt=f'''Use case: identity-preserve. Asset type: production 2D game cutout sprite parts sheet.
Image 1 is the actual original WinterWolfTypeA atlas; Image 2 is its complete serialized original prefab reference. Match that exact simple cartoon design, flat cel shading, dark brown thick outlines, color palette and material shapes. These are reference images, not pixels to rotate or stretch.
Character identity: {identity}
Requested camera: elevated orthographic game camera, strictly axial {direction}. {view}
ONE landscape sheet, exactly FOUR equal columns by TWO equal rows, seven independent detached pieces in reading order. Each piece fully contained in its own cell with 12 percent padding; the last cell is empty. No grid or text.
1. HeadNormal: complete detached head, ears and brown cheek ruff; no chest or torso. {view}
2. HeadAngry: same size, center and ears as HeadNormal; view-appropriate attack head. In rear view EXACT same plain rear head with NO face.
3. HeadDead: same size, center and ears as HeadNormal; view-appropriate dead head. In rear view EXACT same plain rear head with NO face.
4. Body: detached complete four-legged-animal torso ONLY, {body}. The white shoulder collar is integral to torso, small jagged brown fur tufts on broad brown back, not upright humanoid. NO head, ears, legs, feet or tail painted into this slice.
5. LegFront: ONE detached left foreleg; solid rounded brown shoulder root at TOP CENTER, ochre spots, short white lower paw; {feet}. Entire upper root filled with matching brown color; no hollow ring or tube.
6. LegBack: ONE detached left hindleg; rounded brown thigh/hip at TOP CENTER, ochre spots and bent white hock/paw below; {feet}. Solid opaque hip root, no extra leg.
7. Tail: ONE full ivory-white fluffy curved wolf tail with taupe underside shading and thick dark outline; root at BOTTOM CENTER is solid opaque white, curves UP and slightly left. This entire tail is pale, NOT a brown tail with only white tip. Preserve original broad S-shaped bushy fur silhouette; no ring stripes, no limb or rump.
8. EMPTY.
All interiors fully opaque. Exactly flat RGB #FF00FF magenta immediately outside outlines; no magenta interiors. Crisp intact outlines, clean solid connection roots. No assembled creature, no floor, ground shadows, cast shadows, blur, gradient background, halo, checkerboard, labels or watermark. No spines, horns, armor, collar, invented organs, duplicate chest ruff on head or facial details on rear head. Do not remove original ochre spots or recolor ivory fur.
'''
    file.write_text(prompt,encoding='utf-8')
client=Client();project=client.identity()
code='''var paths=new[]{"Assets/Prefabs/Enemy/Enemy_WinterWolfTypeA.prefab","Assets/_UIAssets/Monsters/Dogs/WinterWolfTypeA/WinterWolfTypeA.prefab"};
var controller=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>("Assets/_UIAssets/Monsters/_Common/Animations/Wolf/Controller.controller");
return new {hierarchies=paths.Select(p=>new {path=p,nodes=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p).GetComponentsInChildren<UnityEngine.Transform>(true).Select(t=>new {path=UnityEditor.AnimationUtility.CalculateTransformPath(t,t.root),name=t.name,position=t.localPosition,rotation=t.localEulerAngles,scale=t.localScale,components=t.GetComponents<UnityEngine.Component>().Select(c=>c?c.GetType().FullName:"MISSING").ToArray(),sprite=t.GetComponent<UnityEngine.SpriteRenderer>()?t.GetComponent<UnityEngine.SpriteRenderer>().sprite.name:null}).ToArray()}).ToArray(),parameters=controller.parameters.Select(p=>new {p.name,type=p.type.ToString(),p.defaultInt,p.defaultFloat,p.defaultBool}).ToArray(),clips=controller.animationClips.Distinct().Select(c=>new {path=UnityEditor.AssetDatabase.GetAssetPath(c),c.name,c.length,c.frameRate,loop=UnityEditor.AnimationUtility.GetAnimationClipSettings(c).loopTime,events=UnityEditor.AnimationUtility.GetAnimationEvents(c).Select(e=>new {e.time,e.functionName,e.intParameter,e.stringParameter,e.floatParameter}).ToArray(),floatCurves=UnityEditor.AnimationUtility.GetCurveBindings(c).Select(b=>new {b.path,b.propertyName,type=b.type.FullName,keys=UnityEditor.AnimationUtility.GetEditorCurve(c,b).keys.Select(k=>new {k.time,k.value,k.inTangent,k.outTangent,k.inWeight,k.outWeight,weightedMode=k.weightedMode.ToString()}).ToArray()}).ToArray(),pptrCurves=UnityEditor.AnimationUtility.GetObjectReferenceCurveBindings(c).Select(b=>new {b.path,b.propertyName,type=b.type.FullName,keys=UnityEditor.AnimationUtility.GetObjectReferenceCurve(c,b).Select(k=>new {k.time,value=k.value?k.value.name:null,path=k.value?UnityEditor.AssetDatabase.GetAssetPath(k.value):null}).ToArray()}).ToArray()}).ToArray()};'''
response=client.tool('execute_code',{'action':'execute','code':code})
data=(response.get('structuredContent') or json.loads(response['content'][0]['text']))
assert data['success'],data
(HERE/'source_animation_contract_20261029.json').write_text(json.dumps({'project':project,'response':data,'protocol_history':client.history},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
result=data['data']['result']
print(json.dumps({'hierarchies':result['hierarchies'],'parameters':result['parameters'],'clips':[{k:v for k,v in c.items() if k not in ['floatCurves','pptrCurves']}|{'float_bindings':len(c['floatCurves']),'pptr_bindings':len(c['pptrCurves']),'float_paths':sorted(set(x['path'] for x in c['floatCurves']))} for c in result['clips']]},ensure_ascii=False))
